{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "resolution_time",
  "per_column": [
    {
      "name": "incident_category",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Category of incident (email, vpn, database) is knowable at intake and plausibly correlates with how long resolution takes; genuine predictor outside the focus."
    },
    {
      "name": "incident_symptom_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Symptom (connection_failure, outage, access_denied) is available up front and carries signal about complexity/duration without restating the outcome."
    },
    {
      "name": "scope_indicator",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Blast radius (individual vs server-wide vs department) is a strong, legitimately pre-outcome driver of effort and time."
    },
    {
      "name": "problem_specificity",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "How specific/diagnosable the problem is at intake plausibly predicts resolution effort; derived from description, not from the outcome."
    },
    {
      "name": "remote_access_context",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether the issue involves remote access is knowable early and could affect diagnosis/resolution difficulty."
    },
    {
      "name": "assigned_agent",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Agent identity is exactly the entity the query is about; agent-level speed differences are a core predictive signal for resolution time."
    },
    {
      "name": "reassignment_indicator",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Reassignment typically occurs during the ticket lifecycle and both causes and reflects longer handling; it is largely determined jointly with the resolution process, so it leaks the outcome rather than serving as a clean pre-resolution predictor."
    },
    {
      "name": "ticket_open_status",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Whether the ticket is still open is directly tied to whether/when it was resolved; for unresolved tickets resolution_time is undefined, making this a restatement/leak of the outcome status."
    },
    {
      "name": "opened_day_of_week",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Day opened (weekend vs weekday) is fixed at intake and can affect staffing/queue delays; legitimate temporal predictor."
    },
    {
      "name": "opened_hour_of_day",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "After-hours vs business-hours opening is known at intake and plausibly affects time to first response and resolution."
    }
  ],
  "n_predictors": 8,
  "predictive_utility": 0.7,
  "rationale": "Most added columns are intake-time attributes (category, symptom, scope, specificity, remote context, agent, temporal features) that lie outside resolution_time and carry plausible predictive signal, adding real leverage beyond the raw fields. Two columns—reassignment_indicator and ticket_open_status—are contaminated by the lifecycle/outcome and constitute leakage. As a set the features provide substantial, non-mechanical predictive value, discounted for the leaky pair."
}

